<?php
declare(strict_types=1);

// Módulo de planes y suscripciones.
// Aquí se gestionan los planes, pedidos pendientes y enlaces de pago.
require __DIR__.'/../includes/auth.php';require_login();require_once __DIR__.'/../config/database.php';require __DIR__.'/../includes/payments.php';csrf_check();
$me=$_SESSION['user'];$uid=(int)$me['id'];$role=(string)$me['role'];$flash='';
// En esta ruta, superadmin comparte las herramientas de configuración de planes del administrador.
if($role==='superadmin'){$role='admin';}
if($_SERVER['REQUEST_METHOD']==='POST'){
 $action=(string)($_POST['action']??'');
 try{
  if($role==='admin'&&$action==='plan_update'){$id=(int)($_POST['plan_id']??0);$price=filter_var($_POST['price_cop']??null,FILTER_VALIDATE_INT);$duration=($_POST['duration_days']??'')===''?null:filter_var($_POST['duration_days'],FILTER_VALIDATE_INT);$features=trim((string)($_POST['features']??''));if($price===false||$price<0||$price>2000000000||($duration!==null&&($duration===false||$duration<1||$duration>3650))||mb_strlen($features)>3000)throw new RuntimeException('Precio, duración o características no válidos.');if(!is_array(json_decode($features,true)))throw new RuntimeException('Las características deben ser un arreglo JSON.');$pdo->prepare('UPDATE subscription_plans SET price_cop=?,duration_days=?,features=?,is_available=? WHERE id=?')->execute([$price,$duration,$features,isset($_POST['is_available'])?1:0,$id]);audit_event($pdo,$uid,'subscription.plan_updated',['plan_id'=>$id]);$flash='Plan guardado. Esto no crea ni confirma un cobro.';}
  elseif($role!=='admin'&&$action==='subscription_request'&&getenv('PROSSOR_WOMPI_PUBLIC_KEY')&&getenv('PROSSOR_WOMPI_INTEGRITY_SECRET')){$url=wompi_checkout_url($pdo,(int)($_POST['plan_id']??0),$uid);header('Location: '.$url);exit;}
  elseif($role!=='admin'&&$action==='subscription_request'){$plan=(int)($_POST['plan_id']??0);$q=$pdo->prepare('SELECT id,price_cop FROM subscription_plans WHERE id=? AND is_available=1');$q->execute([$plan]);$row=$q->fetch();if(!$row||(int)$row['price_cop']<=0)throw new RuntimeException('El plan no tiene precio configurado o no está disponible.');$dupe=$pdo->prepare("SELECT id FROM user_subscriptions WHERE user_id=? AND plan_id=? AND status='pending'");$dupe->execute([$uid,$plan]);if(!$dupe->fetchColumn()){$pdo->prepare("INSERT INTO user_subscriptions(user_id,plan_id,status,starts_at) VALUES(?,?,'pending',CURDATE())")->execute([$uid,$plan]);audit_event($pdo,$uid,'subscription.requested',['plan_id'=>$plan]);}$flash='Solicitud pendiente; no se realizó ningún cobro ni se activó el plan.';}
  elseif($action==='subscription_cancel'){$id=(int)($_POST['subscription_id']??0);$q=$pdo->prepare("UPDATE user_subscriptions SET status='cancelled' WHERE id=? AND user_id=? AND status IN ('pending','active')");$q->execute([$id,$uid]);if(!$q->rowCount())throw new RuntimeException('No se encontró una suscripción que puedas cancelar.');audit_event($pdo,$uid,'subscription.cancelled',['subscription_id'=>$id]);$flash='Suscripción cancelada.';}
 }catch(Throwable $e){$flash=$e instanceof RuntimeException?$e->getMessage():'No se pudo guardar la configuración.';}
}
$pdo->exec("UPDATE user_subscriptions SET status='expired' WHERE status='active' AND ends_at<CURDATE()");$plans=$pdo->query('SELECT id,name,price_cop,duration_days,features,is_available FROM subscription_plans ORDER BY price_cop,name')->fetchAll();$q=$pdo->prepare('SELECT s.id,s.status,s.starts_at,s.ends_at,p.name,p.price_cop FROM user_subscriptions s JOIN subscription_plans p ON p.id=s.plan_id WHERE s.user_id=? ORDER BY s.id DESC LIMIT 30');$q->execute([$uid]);$mine=$q->fetchAll();
?><!doctype html><html lang="es"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Planes · Prossor AI</title><link rel="stylesheet" href="../assets/css/app.css"></head><body class="app-body"><main class="main-content"><header class="topbar"><a href="../panel/dashboard.php">← Mi espacio</a><b>Planes y suscripciones</b></header><?php if($flash): ?><div class="notice flash"><?= h($flash) ?></div><?php endif; ?><section class="welcome"><div><p class="eyebrow">ACCESO A FUNCIONES</p><h1>Planes de Prossor</h1><p class="muted">Los precios existentes se conservan. Sin credenciales Wompi, las solicitudes quedan pendientes y no cobran.</p></div></section><div class="stats-grid"><?php foreach($plans as $plan): ?><section class="panel"><h2><?= h($plan['name']) ?></h2><p class="stat-word"><?= (int)$plan['price_cop']>0?'$'.number_format((int)$plan['price_cop'],0,',','.').' COP':'Precio sin configurar' ?></p><p><?= h((string)$plan['features']) ?></p><p class="muted">Duración: <?= $plan['duration_days']?(int)$plan['duration_days'].' días':'sin vencimiento configurado' ?> · <?= (int)$plan['is_available']?'Disponible':'Inactivo' ?></p><?php if($role!=='admin'&&(int)$plan['is_available']&&(int)$plan['price_cop']>0): ?><form method="post"><input type="hidden" name="csrf" value="<?= h(csrf_token()) ?>"><input type="hidden" name="plan_id" value="<?= (int)$plan['id'] ?>"><button class="button light" name="action" value="subscription_request"><?= getenv('PROSSOR_WOMPI_PUBLIC_KEY')?'Continuar a checkout':'Solicitar plan' ?></button></form><?php endif; ?><?php if($role==='admin'): ?><form method="post" class="stack"><input type="hidden" name="csrf" value="<?= h(csrf_token()) ?>"><input type="hidden" name="plan_id" value="<?= (int)$plan['id'] ?>"><label>Precio COP<input type="number" name="price_cop" min="0" max="2000000000" value="<?= (int)$plan['price_cop'] ?>"></label><label>Duración en días (vacío = sin vencimiento)<input type="number" name="duration_days" min="1" max="3650" value="<?= h((string)$plan['duration_days']) ?>"></label><label>Características (JSON)<textarea name="features" maxlength="3000"><?= h((string)$plan['features']) ?></textarea></label><label><input type="checkbox" name="is_available" value="1" <?= (int)$plan['is_available']?'checked':'' ?>> Disponible</label><button class="button light" name="action" value="plan_update">Guardar plan</button></form><?php endif; ?></section><?php endforeach; ?></div><section class="panel"><h2>Mi historial</h2><?php if(!$mine): ?><p class="muted">Aún no tienes solicitudes o suscripciones.</p><?php endif; ?><?php foreach($mine as $sub): ?><article class="plan-row"><div><b><?= h($sub['name']) ?> · <?= h($sub['status']) ?></b><small>Inicio <?= h($sub['starts_at']) ?> · <?= $sub['ends_at']?h($sub['ends_at']):'Sin vencimiento asignado' ?></small></div><?php if(in_array($sub['status'],['pending','active'],true)): ?><form method="post"><input type="hidden" name="csrf" value="<?= h(csrf_token()) ?>"><input type="hidden" name="subscription_id" value="<?= (int)$sub['id'] ?>"><button class="mini-button" name="action" value="subscription_cancel">Cancelar</button></form><?php endif; ?></article><?php endforeach; ?></section><?php if($role==='admin'): ?><section class="panel"><h2>Suscripciones registradas</h2><?php $all=$pdo->query('SELECT s.id,u.name,u.email,p.name plan,s.status,s.starts_at,s.ends_at FROM user_subscriptions s JOIN users u ON u.id=s.user_id JOIN subscription_plans p ON p.id=s.plan_id ORDER BY s.id DESC LIMIT 200')->fetchAll(); ?><div class="table-wrap"><table><thead><tr><th>Usuario</th><th>Correo</th><th>Plan</th><th>Estado</th><th>Inicio</th><th>Vence</th></tr></thead><tbody><?php foreach($all as $r): ?><tr><td><?= h($r['name']) ?></td><td><?= h($r['email']) ?></td><td><?= h($r['plan']) ?></td><td><?= h($r['status']) ?></td><td><?= h($r['starts_at']) ?></td><td><?= h((string)$r['ends_at']) ?></td></tr><?php endforeach; ?></tbody></table></div></section><?php endif; ?></main></body></html>
